-- Add scenarios_summary to dialogflow_references for LLM context
ALTER TABLE public.dialogflow_references
ADD COLUMN IF NOT EXISTS scenarios_summary JSONB;

-- Add comment
COMMENT ON COLUMN public.dialogflow_references.scenarios_summary IS
'Comprehensive summary of all scenarios generated by LLM for use in generation prompts. Includes common_goals, key_differences, integration_strategy, important_considerations, and summary.';

-- Create index
CREATE INDEX IF NOT EXISTS idx_dialogflow_references_scenarios_summary ON dialogflow_references(scenarios_summary);
